// loadingTree reports whether the group tree is still being fetched.
func (m Model) loadingTree() bool { return m.loading || !m.firstLoadDone }

// renderTable renders the table content
func (m Model) renderTable() string {
		// included (SafeCause already ran); the progress stays after it.
		if row, ok := m.clone.table.Selected(); ok {
			st.Detail = components.DescribeItem(jobs.KindClone, row.item).Detail
		}
		return st
	case m.mode == ModeSelecting:
		return components.Status{Text: m.selectionStatusLine()}
	case m.error != "":
		return components.Status{Text: m.error, Level: components.LevelError}
	}
	st := components.Status{}
	switch {
	case m.loadingTree():
		st = components.Status{Text: "Loading " + m.vocab().Name + " " + strings.ToLower(m.vocab().Namespaces) + "...", Activity: true}
	// A level on screen from the index while the forge is asked again: the
	// rows are there, so this is the lowest-priority line, and it says what
	// is still coming rather than that anything is missing.
	case m.refreshing > 0:
		st = components.Status{Text: "Updating from " + m.vocab().Name + "...", Activity: true}
	}
	// The selected row says what it is doing, or what last went wrong on it.
	// Selection mode returned above, so its checkbox column keeps the line.
	if node, ok := m.selectedNode(); ok {
		st.Detail = m.rowActivity(node).Detail
	}
	return st
}

// selectionStatusLine states the selection in the only terms it can: the
// repository count is not known until discovery has run (decision 7), so what
// is shown is what was actually chosen.
func (m Model) selectionStatusLine() string {
	if m.selection.isEmpty() {
		return "Select groups and projects with space, then press enter"
	}
	roots, exclusions := m.selection.counts()
	line := plural(roots, "selection")
	if exclusions > 0 {
		line += " · " + plural(exclusions, "exclusion")
	}
	return line + " — enter to choose a destination"
}

// showsTree reports whether the tree table is what is on screen, which is what
// decides whether the footer carries a breadcrumb and a filter bar.
func (m Model) showsTree() bool {
	if !m.shared.IsAuthenticated || m.loading || m.error != "" || len(m.nodes) == 0 {
		return false
	}
	if m.creationForm != nil {
		return false
	}
	switch m.mode {
	case ModeNormal, ModeSelecting:
		return true
	default:
func (m Model) Init() tea.Cmd {
	if !m.shared.IsAuthenticated {
		return nil
	}
	// The roots are always asked of the forge. When the index already had
	// them, New put them on screen and this is a refresh (seedFromIndex).
	return m.loadRootGroups()
}

// InEditMode returns true if the view is in an edit mode or filter search.
//
	m.updateTableRows()
	m.table.GotoTop()
	return m, nil
}

// handleRootGroupsLoaded lays the decorated roots over what is shown.
func (m Model) handleRootGroupsLoaded(msg RootGroupsLoadedMsg) (tea.Model, tea.Cmd) {
	background := m.refreshingRoots
	if background {
		m.settleRefresh(nil)
		if m.rootsStale {
			m.rootsStale = false
			return m, m.refreshLevel(nil)
		}
	}
	selected := m.selectedPath()
	m.loading = false
	m.firstLoadDone = true
	m.nodes = mergeLevel(m.nodes, msg.Nodes)
	m.error = ""
	m.updateTableRows()
	if background && m.currentGroupNode == nil {
		m.selectRow(selected)
	} else if !background {
		m.table.GotoTop()
	}
	return m, replaceIndexedLevel(nil, m.nodes)
}

// selectedPath is the path under the cursor, empty when there is none. It is
// what keeps the cursor on the same row when a level is re-read in place.
func (m Model) selectedPath() string {
	if node, ok := m.selectedNode(); ok {
		return node.FullPath
	}
	return ""
}

// handleBackgroundLoadError reports a failed refresh of a level that stays on
// screen from the index: the rows are still true as of the last walk, so they
// stay, and the footer says the forge could not be asked.
func (m Model) handleBackgroundLoadError(msg LoadErrorMsg) (tea.Model, tea.Cmd) {
	m.settleRefresh(msg.ParentNode)
	log.Printf("ERROR [explorer] refresh level: %v", msg.Error)
	return m, m.footer.Error("Could not refresh from " + m.vocab().Name + " — showing the last known list")
}

// isBackground reports whether a load error is for a level already shown.
func (m Model) isBackground(msg LoadErrorMsg) bool {
	if msg.ParentNode == nil {
		return m.refreshingRoots
	}
	return !msg.ParentNode.Blocking
}

